const result = $input.first().json?.data?.result;
if (!Array.isArray(result)) {
  throw new Error('Prometheus query returned no vector result');
}

const clusters = ['ggg', 'khb', 'ljw', 'nmg', 'oje'];
const state = Object.fromEntries(clusters.map((cluster) => [cluster, { up: [], up24h: [], ready: null, total: null, pods: {}, restarts: 0 }]));
const alerts = [];
const mgmt = {};

for (const series of result) {
  const metric = series.metric ?? {};
  const kind = metric.digest_kind;
  const value = Number(series.value?.[1] ?? 0);
  const cluster = metric.cluster;

  if (kind === 'alert') {
    alerts.push({
      name: metric.alertname ?? 'UnknownAlert',
      severity: metric.severity ?? 'warning',
      cluster: cluster ?? 'mgmt',
    });
    continue;
  }

  if (kind?.startsWith('mgmt_')) {
    mgmt[kind] = value;
    continue;
  }

  if (!state[cluster]) continue;
  if (kind === 'up') state[cluster].up.push({ job: metric.job ?? 'unknown', instance: metric.instance ?? 'unknown', value });
  if (kind === 'up_24h') state[cluster].up24h.push({ job: metric.job ?? 'unknown', instance: metric.instance ?? 'unknown', value });
  if (kind === 'ready_nodes') state[cluster].ready = value;
  if (kind === 'total_nodes') state[cluster].total = value;
  if (kind === 'pod_phase') state[cluster].pods[metric.phase ?? 'Unknown'] = value;
  if (kind === 'restarts_24h') state[cluster].restarts = value;
}

const actions = [];
for (const alert of alerts) {
  const icon = alert.severity === 'critical' ? '🔴' : '🟡';
  actions.push(`${icon} ${alert.cluster}: ${alert.name} (${alert.severity})`);
}

const statusLines = clusters.map((cluster) => {
  const item = state[cluster];
  const hostVmUp = item.up.some((target) => target.job === 'host-vm' && target.value === 1);
  const ksmUp = item.up.some((target) => target.job === 'kube-state-metrics' && target.value === 1);
  const nodeTargets = item.up.filter((target) => target.job === 'kubernetes-nodes');
  const nodeTargetsUp = nodeTargets.filter((target) => target.value === 1).length;
  const missing = !hostVmUp || !ksmUp || nodeTargets.length === 0 || item.total === null;
  const currentlyDown = item.up.filter((target) => target.value !== 1);
  const historicalDown = item.up24h.filter((target) => target.value !== 1);
  const notReady = item.total === null || item.ready === null ? 0 : Math.max(item.total - item.ready, 0);
  const failedPods = (item.pods.Failed ?? 0) + (item.pods.Unknown ?? 0);
  const pendingPods = item.pods.Pending ?? 0;
  const clusterAlerts = alerts.filter((alert) => alert.cluster === cluster);
  const critical = clusterAlerts.some((alert) => alert.severity === 'critical') || notReady > 0 || failedPods > 0;
  const warning = clusterAlerts.length > 0 || currentlyDown.length > 0 || historicalDown.length > 0 || pendingPods > 0 || item.restarts > 0;

  if (missing) {
    actions.push(`⚪ ${cluster}: 필수 Prometheus 시계열 미수집`);
    return `⚪ ${cluster} — metrics 미수집 · 상태 판정 불가`;
  }

  const details = [
    `Node ${item.ready}/${item.total} Ready`,
    `scrape ${nodeTargetsUp}/${nodeTargets.length}`,
  ];
  if (pendingPods > 0) details.push(`Pending Pod ${pendingPods}`);
  if (failedPods > 0) details.push(`Failed/Unknown Pod ${failedPods}`);
  if (item.restarts > 0) details.push(`24h restart +${Math.round(item.restarts)}`);
  if (historicalDown.length > 0) details.push(`24h target down ${historicalDown.length}`);

  if (critical) return `🔴 ${cluster} — ${details.join(' · ')}`;
  if (warning) return `🟡 ${cluster} — ${details.join(' · ')}`;
  return `🟢 ${cluster} — ${details.join(' · ')}`;
});

const percent = (value) => Number.isFinite(value) ? `${value.toFixed(1)}%` : '미수집';
const timestamp = new Intl.DateTimeFormat('ko-KR', {
  timeZone: 'Asia/Seoul',
  dateStyle: 'medium',
  timeStyle: 'short',
  hour12: false,
}).format(new Date());

const actionSection = actions.length > 0
  ? actions.map((action) => `• ${action}`).join('\n')
  : '• 없음';
const text = [
  `☀️ *ACER 전체 운영 다이제스트* — ${timestamp} KST`,
  '',
  '*조치 필요*',
  actionSection,
  '',
  '*클러스터 상태*',
  ...statusLines,
  '',
  '*mgmt*',
  `• CPU ${percent(mgmt.mgmt_cpu_pct)} · MEM ${percent(mgmt.mgmt_mem_pct)} · Disk ${percent(mgmt.mgmt_disk_pct)}`,
].join('\n');

return [{ json: { text } }];
